mapper.select:
select user_id, git_name, source, evidence_commit, evidence_at, verified_at
from user_scm_git_identities
where user_id = #{userId}

mapper.insert:
merge into user_scm_git_identities target using (values
(cast(#{row.userId} as varchar(128)), cast(#{row.gitName} as varchar(128)), cast(#{row.source} as varchar(32)), cast(#{row.evidenceCommit} as varchar(64)), cast(#{row.evidenceAt} as timestamp), cast(#{row.verifiedAt} as timestamp), cast(#{now} as timestamp), cast(#{now} as timestamp))
) incoming(user_id, git_name, identity_source, evidence_commit, evidence_at, verified_at, created_at, updated_at) on target.user_id = incoming.user_id when matched and target.source = 'ACCEPTED_COMMIT_HISTORY' and (target.evidence_at < incoming.evidence_at or (target.evidence_at = incoming.evidence_at and (coalesce(target.evidence_commit, '') < coalesce(incoming.evidence_commit, '') or (coalesce(target.evidence_commit, '') = coalesce(incoming.evidence_commit, '') and target.git_name <> incoming.git_name)))) then update set git_name = incoming.git_name, source = incoming.identity_source, evidence_commit = incoming.evidence_commit, evidence_at = incoming.evidence_at, verified_at = incoming.verified_at, updated_at = incoming.updated_at when not matched then insert ( user_id, git_name, source, evidence_commit, evidence_at, verified_at, created_at, updated_at ) values ( incoming.user_id, incoming.git_name, incoming.identity_source, incoming.evidence_commit, incoming.evidence_at, incoming.verified_at, incoming.created_at, incoming.updated_at )

insert into user_scm_git_identities(
    user_id, git_name, source, evidence_commit, evidence_at, verified_at, created_at, updated_at
) values (
    #{row.userId}, #{row.gitName}, #{row.source}, #{row.evidenceCommit},
    #{row.evidenceAt}, #{row.verifiedAt}, #{now}, #{now}
)
on conflict (user_id) do update set
    git_name = excluded.git_name, source = excluded.source,
    evidence_commit = excluded.evidence_commit, evidence_at = excluded.evidence_at,
    verified_at = excluded.verified_at, updated_at = excluded.updated_at

merge into user_scm_git_identities(
    user_id, git_name, source, evidence_commit, evidence_at, verified_at, created_at, updated_at
) key(user_id) values (
    #{row.userId}, #{row.gitName}, #{row.source}, #{row.evidenceCommit},
    #{row.evidenceAt}, #{row.verifiedAt}, #{now}, #{now}
)
